BEGIN TRANSACTION;
CREATE TABLE agents (
	agent_id INTEGER NOT NULL, 
	agent_name VARCHAR(100) NOT NULL, 
	team_id INTEGER NOT NULL, 
	workload_capacity INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (agent_id), 
	FOREIGN KEY(team_id) REFERENCES teams (team_id)
);
CREATE TABLE assignments (
	assignment_id INTEGER NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	team_id INTEGER NOT NULL, 
	agent_id INTEGER NOT NULL, 
	assigned_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	assigned_by VARCHAR(100) NOT NULL, 
	reason TEXT, 
	is_current BOOLEAN NOT NULL, 
	PRIMARY KEY (assignment_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id), 
	FOREIGN KEY(team_id) REFERENCES teams (team_id), 
	FOREIGN KEY(agent_id) REFERENCES agents (agent_id)
);
CREATE TABLE categories (
	category_id INTEGER NOT NULL, 
	category_name VARCHAR(100) NOT NULL, 
	description TEXT, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (category_id), 
	UNIQUE (category_name)
);
CREATE TABLE complaint_events (
	event_id INTEGER NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	event_type VARCHAR(50) NOT NULL, 
	old_value VARCHAR(100), 
	new_value VARCHAR(100), 
	description TEXT, 
	performed_by VARCHAR(100) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (event_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id)
);
CREATE TABLE complaint_messages (
	message_id VARCHAR(60) NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	sender_type VARCHAR(30) NOT NULL, 
	message_text TEXT NOT NULL, 
	channel VARCHAR(30) NOT NULL, 
	is_internal BOOLEAN NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (message_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id)
);
CREATE TABLE complaint_products (
	complaint_product_id INTEGER NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	product_id VARCHAR(30) NOT NULL, 
	issue_description TEXT, 
	PRIMARY KEY (complaint_product_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id), 
	FOREIGN KEY(product_id) REFERENCES products (product_id)
);
CREATE TABLE complaints (
	complaint_id VARCHAR(30) NOT NULL, 
	customer_id VARCHAR(20) NOT NULL, 
	order_id VARCHAR(30), 
	category_id INTEGER NOT NULL, 
	description TEXT NOT NULL, 
	channel VARCHAR(30) NOT NULL, 
	sentiment VARCHAR(30) NOT NULL, 
	severity VARCHAR(30) NOT NULL, 
	priority VARCHAR(10) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	recurrence_count INTEGER NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (complaint_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id), 
	FOREIGN KEY(order_id) REFERENCES orders (order_id), 
	FOREIGN KEY(category_id) REFERENCES categories (category_id)
);
CREATE TABLE customers (
	customer_id VARCHAR(20) NOT NULL, 
	full_name VARCHAR(100) NOT NULL, 
	email VARCHAR(150) NOT NULL, 
	phone VARCHAR(20) NOT NULL, 
	region VARCHAR(100) NOT NULL, 
	is_vulnerable BOOLEAN NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (customer_id), 
	UNIQUE (email)
);
CREATE TABLE order_items (
	order_item_id INTEGER NOT NULL, 
	order_id VARCHAR(30) NOT NULL, 
	product_id VARCHAR(30) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(12, 2) NOT NULL, 
	line_total NUMERIC(12, 2) NOT NULL, 
	PRIMARY KEY (order_item_id), 
	FOREIGN KEY(order_id) REFERENCES orders (order_id), 
	FOREIGN KEY(product_id) REFERENCES products (product_id)
);
CREATE TABLE orders (
	order_id VARCHAR(30) NOT NULL, 
	customer_id VARCHAR(20) NOT NULL, 
	order_date DATETIME NOT NULL, 
	total_amount NUMERIC(12, 2) NOT NULL, 
	payment_status VARCHAR(30) NOT NULL, 
	order_status VARCHAR(30) NOT NULL, 
	shipping_region VARCHAR(100) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (order_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE priority_decision_rules (
	id INTEGER NOT NULL, 
	decision_id INTEGER NOT NULL, 
	rule_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(decision_id) REFERENCES priority_decisions (decision_id), 
	FOREIGN KEY(rule_id) REFERENCES priority_rules (rule_id)
);
CREATE TABLE priority_decisions (
	decision_id INTEGER NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	calculated_score INTEGER NOT NULL, 
	assigned_priority VARCHAR(10) NOT NULL, 
	safety_override_applied VARCHAR(10), 
	explanation VARCHAR(500) NOT NULL, 
	decided_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (decision_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id)
);
CREATE TABLE priority_rules (
	rule_id INTEGER NOT NULL, 
	rule_name VARCHAR(100) NOT NULL, 
	condition_type VARCHAR(50) NOT NULL, 
	condition_value VARCHAR(100) NOT NULL, 
	score INTEGER NOT NULL, 
	priority_override VARCHAR(10), 
	is_active BOOLEAN NOT NULL, 
	effective_from DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	effective_to DATETIME, 
	PRIMARY KEY (rule_id)
);
CREATE TABLE products (
	product_id VARCHAR(30) NOT NULL, 
	product_name VARCHAR(150) NOT NULL, 
	category_name VARCHAR(100) NOT NULL, 
	unit_price NUMERIC(12, 2) NOT NULL, 
	is_safety_sensitive BOOLEAN NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (product_id)
);
CREATE TABLE resolutions (
	resolution_id VARCHAR(60) NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	resolution_type VARCHAR(50) NOT NULL, 
	resolution_description TEXT NOT NULL, 
	resolved_by INTEGER NOT NULL, 
	resolved_at DATETIME NOT NULL, 
	is_final BOOLEAN NOT NULL, 
	PRIMARY KEY (resolution_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id), 
	FOREIGN KEY(resolved_by) REFERENCES agents (agent_id)
);
CREATE TABLE sla_clocks (
	sla_id VARCHAR(60) NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	priority VARCHAR(10) NOT NULL, 
	response_deadline DATETIME NOT NULL, 
	resolution_deadline DATETIME NOT NULL, 
	first_response_at DATETIME, 
	resolved_at DATETIME, 
	paused_at DATETIME, 
	total_paused_seconds INTEGER NOT NULL, 
	response_breached BOOLEAN NOT NULL, 
	resolution_breached BOOLEAN NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (sla_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id)
);
CREATE TABLE surveys (
	survey_id INTEGER NOT NULL, 
	resolution_id VARCHAR(60) NOT NULL, 
	complaint_id VARCHAR(30) NOT NULL, 
	rating INTEGER NOT NULL, 
	feedback TEXT, 
	submitted_at DATETIME NOT NULL, 
	PRIMARY KEY (survey_id), 
	CONSTRAINT check_survey_rating CHECK (rating >= 1 AND rating <= 5), 
	UNIQUE (resolution_id), 
	FOREIGN KEY(resolution_id) REFERENCES resolutions (resolution_id), 
	FOREIGN KEY(complaint_id) REFERENCES complaints (complaint_id)
);
CREATE TABLE teams (
	team_id INTEGER NOT NULL, 
	team_name VARCHAR(100) NOT NULL, 
	description TEXT, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (team_id), 
	UNIQUE (team_name)
);
CREATE INDEX ix_customers_customer_id ON customers (customer_id);
CREATE INDEX ix_products_product_id ON products (product_id);
CREATE INDEX ix_orders_customer_id ON orders (customer_id);
CREATE INDEX ix_orders_order_id ON orders (order_id);
CREATE INDEX ix_agents_team_id ON agents (team_id);
CREATE INDEX ix_order_items_order_id ON order_items (order_id);
CREATE INDEX ix_order_items_product_id ON order_items (product_id);
CREATE INDEX ix_complaints_complaint_id ON complaints (complaint_id);
CREATE INDEX ix_complaints_customer_id ON complaints (customer_id);
CREATE INDEX ix_complaint_products_product_id ON complaint_products (product_id);
CREATE INDEX ix_complaint_products_complaint_id ON complaint_products (complaint_id);
CREATE INDEX ix_complaint_messages_complaint_id ON complaint_messages (complaint_id);
CREATE INDEX ix_assignments_complaint_id ON assignments (complaint_id);
CREATE INDEX ix_sla_clocks_complaint_id ON sla_clocks (complaint_id);
CREATE INDEX ix_resolutions_complaint_id ON resolutions (complaint_id);
CREATE INDEX ix_complaint_events_complaint_id ON complaint_events (complaint_id);
CREATE INDEX ix_priority_decisions_complaint_id ON priority_decisions (complaint_id);
CREATE INDEX ix_priority_decision_rules_rule_id ON priority_decision_rules (rule_id);
CREATE INDEX ix_priority_decision_rules_decision_id ON priority_decision_rules (decision_id);
COMMIT;
